16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "membership_tier")
66	    private String membershipTier;
67	
68	    @Transient
69	    private Integer namesakeCount;
70	
71	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
72	    private Set<Pet> pets;
73	
74	    /**
75	     * Ensures a newly persisted owner has a registration date. When an owner is created without
76	     * one, it defaults to today's date.
77	     */
78	    @PrePersist
79	    protected void onRegister() {
80	        if (this.registrationDate == null) {
81	            this.registrationDate = LocalDate.now();
82	        }
83	    }
84	
85	    public String getAddress() {
86	        return this.address;
87	    }
88	
89	    public void setAddress(String address) {
90	        this.address = address;
91	    }
92	
93	    public String getCity() {
94	        return this.city;
95	    }
96	
97	    public void setCity(String city) {
98	        this.city = city;
99	    }
100	
101	    public String getTelephone() {
102	        return this.telephone;
103	    }
104	
105	    public void setTelephone(String telephone) {
106	        this.telephone = telephone;
107	    }
108	
109	    public String getEmail() {
110	        return this.email;
111	    }
112	
113	    public void setEmail(String email) {
114	        this.email = email;
115	    }
116	
117	    public LocalDate getRegistrationDate() {
118	        return this.registrationDate;
119	    }
120	
121	    public void setRegistrationDate(LocalDate registrationDate) {
122	        this.registrationDate = registrationDate;
123	    }
124	
125	    public Integer getMembershipNumber() {
126	        return this.membershipNumber;
127	    }
128	
129	    public void setMembershipNumber(Integer membershipNumber) {
130	        this.membershipNumber = membershipNumber;
131	    }
132	
133	    public String getCustomerCode() {
134	        return this.customerCode;
135	    }
136	
137	    public void setCustomerCode(String customerCode) {
138	        this.customerCode = customerCode;
139	    }
140	
141	    public String getMembershipTier() {
142	        return this.membershipTier;
143	    }
144	
145	    public void setMembershipTier(String membershipTier) {
146	        this.membershipTier = membershipTier;
147	    }
148	
149	    public Integer getNamesakeCount() {
150	        return this.namesakeCount;
151	    }
152	
153	    public void setNamesakeCount(Integer namesakeCount) {
154	        this.namesakeCount = namesakeCount;
155	    }
156	
157	    protected Set<Pet> getPetsInternal() {
158	        if (this.pets == null) {
159	            this.pets = new HashSet<>();
160	        }
161	        return this.pets;
162	    }
163	
164	    protected void setPetsInternal(Set<Pet> pets) {
165	        this.pets = pets;
166	    }
167	
168	    public List<Pet> getPets() {
169	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
170	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
171	        return Collections.unmodifiableList(sortedPets);
172	    }
173	
174	    public void setPets(List<Pet> pets) {
175	        this.pets = new HashSet<>(pets);
176	    }
177	
178	    public void addPet(Pet pet) {
179	        getPetsInternal().add(pet);
180	        pet.setOwner(this);
181	    }
182	
183	    /**
184	     * Return the Pet with the given name, or null if none found for this Owner.
185	     *
186	     * @param name to test
187	     * @return true if pet name is already in use
188	     */
189	    public Pet getPet(String name) {
190	        return getPet(name, false);
191	    }
192	
193	    /**
194	     * Return the Pet with the given name, or null if none found for this Owner.
195	     *
196	     * @param name to test
197	     * @return true if pet name is already in use
198	     */
199	    public Pet getPet(String name, boolean ignoreNew) {
200	        name = name.toLowerCase();
201	        for (Pet pet : getPetsInternal()) {
202	            if (!ignoreNew || !pet.isNew()) {
203	                String compName = pet.getName();
204	                compName = compName.toLowerCase();
205	                if (compName.equals(name)) {
206	                    return pet;
207	                }
208	            }
209	        }
210	        return null;
211	    }
212	
213	    public Pet getPet(Integer petId) {
214	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
215	    }
216	
217	    @Override
218	    public String toString() {
219	        return new ToStringCreator(this)
220	
221	            .append("id", this.getId())
222	            .append("new", this.isNew())
223	            .append("lastName", this.getLastName())
224	            .append("firstName", this.getFirstName())
225	            .append("address", this.address)
226	            .append("city", this.city)
227	            .append("telephone", this.telephone)
228	            .toString();
229	    }
230	}
