1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    OwnerDto toOwnerDto(Owner owner);
24	
25	    Owner toOwner(OwnerDto ownerDto);
26	
27	    @Mapping(target = "id", ignore = true)
28	    @Mapping(target = "pets", ignore = true)
29	    Owner toOwner(OwnerFieldsDto ownerDto);
30	
31	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
32	
33	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
34	
35	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
36	        OwnerPageDto ownerPageDto = new OwnerPageDto();
37	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
38	        ownerPageDto.setPage(ownerPage.getNumber());
39	        ownerPageDto.setSize(ownerPage.getSize());
40	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
41	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
42	        return ownerPageDto;
43	    }
44	}
