1	package org.springframework.samples.petclinic.acceptance;
2	
3	import static org.junit.jupiter.api.Assertions.assertFalse;
4	import static org.junit.jupiter.api.Assertions.assertTrue;
5	
6	import org.junit.jupiter.api.Tag;
7	import org.junit.jupiter.api.Test;
8	
9	import tools.jackson.databind.node.ObjectNode;
10	
11	/** cp17: sharesHousehold = another owner already has the same address and city. */
12	@Tag("cp17")
13	class Cp17Tests extends AcceptanceBase {
14	
15		@Test
16		void coreHouseholdFlag() throws Exception {
17			String address = uniqueAddress();
18			String city = uniqueCity();
19	
20			ObjectNode a = ownerNode();
21			a.put("address", address);
22			a.put("city", city);
23			boolean first = fetchOwner(createOwnerOk(a)).get("sharesHousehold").asBoolean();
24	
25			ObjectNode b = ownerNode(); // same address + city, own unique name/phone
26			b.put("address", address);
27			b.put("city", city);
28			boolean second = fetchOwner(createOwnerOk(b)).get("sharesHousehold").asBoolean();
29	
30			assertFalse(first, "first owner at the address shares no household");
31			assertTrue(second, "second owner at the same address + city shares a household");
32		}
33	}
