31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (hasReachedDailyRegistrationLimit()) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (hasReachedCityOwnerLimit(owner.getCity())) {
112	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	        }
114	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
118	        owner.setCity(resolveCity(owner.getCity()));
119	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
120	        owner.setMembershipNumber(membershipNumber);
121	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
122	        owner.setMembershipTier(membershipNumber <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        currentOwner.setAddress(ownerFieldsDto.getAddress());
138	        currentOwner.setCity(ownerFieldsDto.getCity());
139	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
140	        currentOwner.setLastName(ownerFieldsDto.getLastName());
141	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
142	        this.clinicService.saveOwner(currentOwner);
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Transactional
148	    @Override
149	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        this.clinicService.deleteOwner(owner);
155	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        HttpHeaders headers = new HttpHeaders();
166	        Pet pet = petMapper.toPet(petFieldsDto);
167	        owner.setId(ownerId);
168	        pet.setOwner(owner);
169	        pet.getType().setName(null);
170	        this.clinicService.savePet(pet);
171	        PetDto petDto = petMapper.toPetDto(pet);
172	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
173	            .buildAndExpand(pet.getId()).toUri());
174	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner != null) {
182	            Pet currentPet = this.clinicService.findPetById(petId);
183	            if (currentPet != null) {
184	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
185	                currentPet.setName(petFieldsDto.getName());
186	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
187	                this.clinicService.savePet(currentPet);
188	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	            }
190	        }
191	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
197	        HttpHeaders headers = new HttpHeaders();
198	        Visit visit = visitMapper.toVisit(visitFieldsDto);
199	        Pet pet = new Pet();
200	        pet.setId(petId);
201	        visit.setPet(pet);
202	        this.clinicService.saveVisit(visit);
203	        VisitDto visitDto = visitMapper.toVisitDto(visit);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
205	            .buildAndExpand(visit.getId()).toUri());
206	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
207	    }
208	
209	
210	    /**
211	     * The number of owners at the head of the registration sequence that receive the
212	     * {@code 'FOUNDING'} membership tier. The first {@value #MAX_FOUNDING_OWNERS} owners ever
213	     * created are {@code 'FOUNDING'}; all later owners are {@code 'STANDARD'}.
214	     */
215	    private static final int MAX_FOUNDING_OWNERS = 100;
216	
217	    /**
218	     * The maximum number of owners that may be registered on any single calendar day.
219	     */
220	    private static final long MAX_DAILY_REGISTRATIONS = 20;
221	
222	    /**
223	     * Determines whether the daily owner-registration limit has already been reached. Owners are
224	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
225	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
226	     * owners may be created today.
227	     *
228	     * @return {@code true} if today's registration limit has been reached
229	     */
230	    private boolean hasReachedDailyRegistrationLimit() {
231	        LocalDate today = LocalDate.now();
232	        long registeredToday = this.clinicService.findAllOwners().stream()
233	            .filter(existing -> today.equals(existing.getRegistrationDate()))
234	            .count();
235	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
236	    }
237	
238	    /**
239	     * The maximum number of owners that may be registered in any single city.
240	     */
241	    private static final long MAX_OWNERS_PER_CITY = 8;
242	
243	    /**
244	     * Determines whether the given city has already reached its owner limit. Owners are matched to
245	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
246	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
247	     * no further owners may be created there.
248	     *
249	     * @param city the city of the new owner, may be {@code null}
250	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
251	     */
252	    private boolean hasReachedCityOwnerLimit(String city) {
253	        String normalized = normalize(city);
254	        long ownersInCity = this.clinicService.findAllOwners().stream()
255	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
256	            .count();
257	        return ownersInCity >= MAX_OWNERS_PER_CITY;
258	    }
259	
260	    /**
261	     * Builds the customer code for a newly created owner, formatted as
262	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
263	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
264	     *
265	     * @param city the city of the new owner
266	     * @return the assigned customer code
267	     */
268	    private String nextCustomerCode(String city) {
269	        long ownersInCity = this.clinicService.findAllOwners().stream()
270	            .filter(existing -> Objects.equals(
271	                normalize(existing.getCity()), normalize(city)))
272	            .count();
273	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
274	    }
275	
276	    /**
277	     * Resolves the city to store for a newly created owner. The city is title-cased (so
278	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
279	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
280	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
281	     * surrounding or repeated whitespace.
282	     *
283	     * @param city the city supplied for the new owner, may be {@code null}
284	     * @return the city to store, or {@code null} if the input was {@code null}
285	     */
286	    private String resolveCity(String city) {
287	        if (city == null) {
288	            return null;
289	        }
290	        String normalized = normalize(city);
291	        if (!normalized.isEmpty()) {
292	            for (Owner existing : this.clinicService.findAllOwners()) {
293	                if (normalized.equals(normalize(existing.getCity()))) {
294	                    return existing.getCity();
295	                }
296	            }
297	        }
298	        return toTitleCase(city);
299	    }
300	
301	    /**
302	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
303	     * and lower-casing the remaining letters, preserving the original whitespace. For example
304	     * {@code "new  YORK"} becomes {@code "New  York"}.
305	     *
306	     * @param value the raw value, never {@code null}
307	     * @return the title-cased value
308	     */
309	    private static String toTitleCase(String value) {
310	        StringBuilder result = new StringBuilder(value.length());
311	        boolean startOfWord = true;
312	        for (int i = 0; i < value.length(); i++) {
313	            char c = value.charAt(i);
314	            if (Character.isWhitespace(c)) {
315	                startOfWord = true;
316	                result.append(c);
317	            } else if (startOfWord) {
318	                result.append(Character.toTitleCase(c));
319	                startOfWord = false;
320	            } else {
321	                result.append(Character.toLowerCase(c));
322	            }
323	        }
324	        return result.toString();
325	    }
326	
327	    /**
328	     * Counts how many existing owners share the given last name. Last names are matched using
329	     * {@link #normalize(String)}, so the count ignores letter case and any surrounding or repeated
330	     * whitespace. This is evaluated against the owners present at the moment the new owner is
331	     * created, before the new owner is persisted, so the new owner does not count itself.
332	     *
333	     * @param lastName the last name of the new owner, may be {@code null}
334	     * @return the number of existing owners sharing the same last name
335	     */
336	    private int countNamesakes(String lastName) {
337	        String normalized = normalize(lastName);
338	        return (int) this.clinicService.findAllOwners().stream()
339	            .filter(existing -> normalized.equals(normalize(existing.getLastName())))
340	            .count();
341	    }
342	
343	    /**
344	     * Determines whether the given telephone number is already used by any other owner.
345	     *
346	     * @param owner the candidate owner
347	     * @return {@code true} if an owner with the same telephone number already exists in the data store
348	     */
349	    private boolean isDuplicateOwner(Owner owner) {
350	        return this.clinicService.findAllOwners().stream()
351	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
352	    }
353	
354	    /**
355	     * Determines whether the given email address is already used by any other owner. An owner
356	     * without an email address is never considered a duplicate on this criterion. Email addresses
357	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
358	     * surrounding or repeated whitespace.
359	     *
360	     * @param owner the candidate owner
361	     * @return {@code true} if the owner provides an email already used by an existing owner
362	     */
363	    private boolean isDuplicateEmail(Owner owner) {
364	        String email = normalize(owner.getEmail());
365	        if (email.isEmpty()) {
366	            return false;
367	        }
368	        return this.clinicService.findAllOwners().stream()
369	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
370	    }
371	
372	    /**
373	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
374	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
375	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
376	     * differently formatted representations of the same number are treated as duplicates. A
377	     * {@code null} value is returned unchanged.
378	     *
379	     * @param telephone the raw telephone number, may be {@code null}
380	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
381	     */
382	    private static String normalizeTelephone(String telephone) {
383	        if (telephone == null) {
384	            return null;
385	        }
386	        return telephone.replaceAll("[\\s()-]", "");
387	    }
388	
389	    /**
390	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
391	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
392	     * collapsed to a single space and the result is lower-cased. This is what makes
393	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
394	     * duplicates. A {@code null} value normalizes to the empty string.
395	     *
396	     * @param value the raw value, may be {@code null}
397	     * @return the normalized value, never {@code null}
398	     */
399	    private static String normalize(String value) {
400	        if (value == null) {
401	            return "";
402	        }
403	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
404	    }
405	
406	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
407	    @Override
408	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
409	        Owner owner = this.clinicService.findOwnerById(ownerId);
410	        if (owner != null) {
411	            Pet pet = owner.getPet(petId);
412	            if (pet != null) {
413	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
414	            }
415	        }
416	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
417	    }
418	}
